Simulador.imagens = {"urbanSkater": "data:image/jpeg;base64,", "neonStriker": "data:image/jpeg;base64,", "tribalBalance": "data:image/jpeg;base64,", "tribal2": "data:image/jpeg;base64,", "stealthMartial": "data:image/jpeg;base64,", "futuroBananeira": "data:image/jpeg;base64,", "classicChute": "data:image/jpeg;base64,", "reggaeRhythm": "data:image/jpeg;base64,", "mysticFlow": "data:image/jpeg;base64,", "onca": "data:image/jpeg;base64,", "professor": "data:image/jpeg;base64,", "agulha": "data:image/png;base64,", "sereno": "data:image/jpeg;base64,"};

Simulador.graduacoes = [
  "Crua", "Crua e Amarela", "Amarela", "Amarela e Crua", "Laranja",
  "Amarela e Laranja", "Corda Laranja", "Crua e Azul", "Amarela e Azul",
  "Laranja e Azul", "Azul", "Azul e Verde", "Verde", "Verde e Roxa",
  "Roxa", "Roxa e Marrom", "Marrom", "Marrom e Vermelha", "Vermelha"
];

Simulador.personagens = (function () {
  var dados = {
    rootsGinga:      { nome: "Roots Ginga", atributos:{forca:85,velocidade:60,agilidade:75}, movimentos:["Ginga Tradicional","Rasteira","Meia-Lua de Compasso"], especial:"Chamada de Angola" },
    urbanSkater:     { nome: "Urban Skater", atributos:{forca:65,velocidade:90,agilidade:85}, movimentos:["Ginga Veloz","Martelo Rodado","Au Sem Mao"], especial:"Drop do Skate" },
    neonStriker:     { nome: "Neon Striker", atributos:{forca:75,velocidade:85,agilidade:80}, movimentos:["Ginga Eletrica","Armada","Queixada Neon"], especial:"Combo Relampago" },
    tribalBalance:   { nome: "Tribal Balance", atributos:{forca:70,velocidade:75,agilidade:90}, movimentos:["Ginga Cadenciada","Bencao","Au de Cabeca"], especial:"Toque do Berimbau" },
    tribal2:         { nome: "Tribal 2", atributos:{forca:80,velocidade:70,agilidade:80}, movimentos:["Ginga Firme","Chute Frontal Tatico","Voo do Morcego"], especial:"Escudo Cibernetico" },
    stealthMartial:  { nome: "Stealth Martial", atributos:{forca:70,velocidade:95,agilidade:95}, movimentos:["Ginga Agachada","Mortal Trancado","Corta-Capim Furtivo"], especial:"Ataque Fantasma" },
    futuroBananeira: { nome: "Futuro Bananeira", atributos:{forca:75,velocidade:80,agilidade:95}, movimentos:["Ginga Invertida","Bananeira Estatica","Queda de Rins"], especial:"Au Batido Infinito" },
    classicChute:    { nome: "Classic Chute", atributos:{forca:85,velocidade:75,agilidade:70}, movimentos:["Ginga Padrao","Martelo de Pe","Chute Frontal Cruzado"], especial:"Bencao Devastadora" },
    reggaeRhythm:    { nome: "Reggae Rhythm", atributos:{forca:68,velocidade:72,agilidade:85}, movimentos:["Ginga Gingada","Rasteira em Circulo","Au Agulha"], especial:"Onda de Vibracao" },
    mysticFlow:      { nome: "Mystic Flow", atributos:{forca:60,velocidade:85,agilidade:95}, movimentos:["Ginga Leve","Meia-Lua Flutuante","Esquiva Fluida"], especial:"Fluxo Mistico" },
    sereno:          { nome: "Sereno", atributos:{forca:75,velocidade:80,agilidade:90}, movimentos:["Ginga Serena","Bananeira Livre","Au Sem Mao"], especial:"Equilibrio Total" },
    agulha:          { nome: "Agulha", atributos:{forca:70,velocidade:80,agilidade:85}, movimentos:["Ginga Precisa","Au Agulha","Rasteira Cruzada"], especial:"Ponto Certeiro" },
    onca:            { nome: "Onca", atributos:{forca:88,velocidade:82,agilidade:88}, movimentos:["Ginga Felina","Rasteira da Onca","Bote Certeiro"], especial:"Salto da Onca" },
    professor:       { nome: "Professor / Mestre", atributos:{forca:95,velocidade:85,agilidade:90}, movimentos:["Ginga do Mestre","Rasteira Ensinada","Golpe de Autoridade"], especial:"Chamada do Mestre", exclusivo:"professor" }
  };
  function congelar(o) {
    Object.getOwnPropertyNames(o).forEach(function (k) {
      if (o[k] && typeof o[k] === "object") congelar(o[k]);
    });
    return Object.freeze(o);
  }
  return congelar(dados);
})();

/* energia fica SEPARADA dos dados congelados, só assim ela consegue mudar de verdade */
Simulador.estadoBatalha = {};
Simulador.resetarEstadoBatalha = function () {
  var e = {};
  Object.keys(Simulador.personagens).forEach(function (k) { e[k] = { energia: 100 }; });
  Simulador.estadoBatalha = e;
};
Simulador.resetarEstadoBatalha();

Simulador.executarMovimento = function (chave, indice) {
  var p = Simulador.personagens[chave];
  var estado = Simulador.estadoBatalha[chave];
  if (!p || !estado) return "Personagem nao encontrado.";
  if (estado.energia < 15) return p.nome + " esta exausto! Precisa descansar na ginga.";
  var golpe = p.movimentos[indice] || p.especial;
  var custo = (golpe === p.especial) ? 30 : 15;
  estado.energia = Math.max(0, estado.energia - custo);
  var precisao = Math.floor(Math.random() * p.atributos.agilidade);
  var impacto = Math.floor((p.atributos.forca * p.atributos.velocidade) / 100);
  return { texto: p.nome + " aplicou [" + golpe + "]!", precisao: precisao, impacto: impacto, energiaRestante: estado.energia };
};

Simulador.descansar = function (chave) {
  var estado = Simulador.estadoBatalha[chave];
  if (estado) estado.energia = Math.min(100, estado.energia + 25);
};

Simulador.avatarSelecionadoTemp = null;

/* ------------------------------------------------------------
   Renderização principal: decide se mostra tela de escolha de
   avatar (se o aluno logado ainda não tem um) ou o jogo direto.
   ------------------------------------------------------------ */
/* Porta de entrada do Mundo Aberto: unifica Simulador + Terreiro + Tamagotchi.
   Sem cadastro → mostra a academia e pede cadastro/login. */
Simulador.entrarMundoAberto = function () {
  abrirAba('tabSimulador');
};

Simulador.render = function () {
  var aluno = (typeof alunoLogado === "function") ? alunoLogado() : null;
  var areaLogin = $('simAreaLogin');
  var areaJogo = $('simAreaJogo');

  if (!aluno) {
    areaJogo.style.display = "none";
    areaLogin.style.display = "block";
    areaLogin.innerHTML =
      '<div class="card card-destaque brilho-verde" style="border:1px solid var(--primary-green);">' +
        '<h3><i class="fas fa-globe"></i> Mundo Aberto — Academia</h3>' +
        '<p style="font-size:0.8rem;margin-bottom:8px;">Bem-vindo ao Universo Capoeira! Aqui ficam o <b>avatar</b>, o <b>Terreiro</b>, o cuidado estilo Tamagotchi e o treino/combate — tudo num só lugar.</p>' +
        '<p class="mini" style="margin-bottom:10px;">Para entrar no mundo você precisa estar cadastrado na academia.</p>' +
        '<button class="btn" onclick="Simulador.pedirCadastroAcademia()"><i class="fas fa-user-plus"></i> Cadastrar na Academia</button>' +
        '<button class="btn btn-secondary" onclick="Simulador.pedirLoginAcademia()"><i class="fas fa-sign-in-alt"></i> Já tenho conta — Entrar</button>' +
      '</div>' +
      '<div class="card">' +
        '<h3><i class="fas fa-info-circle"></i> O que você encontra no Mundo</h3>' +
        '<ul class="mini" style="padding-left:18px;line-height:1.6;">' +
          '<li>Avatar que aprende com seus treinos</li>' +
          '<li>Terreiro virtual com quem está online</li>' +
          '<li>Cuidar do avatar (fome, humor, energia)</li>' +
          '<li>Combate e movimentos de capoeira</li>' +
        '</ul>' +
      '</div>';
    return;
  }

  if (!aluno.avatarSimulador) {
    areaLogin.style.display = "block";
    areaJogo.style.display = "none";
    Simulador.renderEscolhaAvatar(aluno);
  } else {
    areaLogin.style.display = "none";
    areaJogo.style.display = "block";
    Simulador.iniciarJogo(aluno);
  }
};

Simulador.pedirCadastroAcademia = function () {
  abrirAba('tab3');
  setTimeout(function () {
    try {
      if (typeof toggleAutoCadastroAluno === 'function') toggleAutoCadastroAluno(true);
      try { mostrarToast('Cadastre-se para entrar no Mundo Aberto!'); } catch (e) {}
      var card = $('cardAlunoPrimeiroCadastro');
      if (card) card.scrollIntoView({ behavior: 'smooth', block: 'start' });
    } catch (e2) {}
  }, 200);
};

Simulador.pedirLoginAcademia = function () {
  abrirAba('tab3');
  setTimeout(function () {
    try {
      if (typeof toggleAutoCadastroAluno === 'function') toggleAutoCadastroAluno(false);
      try { mostrarToast('Entre com sua conta para acessar o Mundo.'); } catch (e) {}
      var card = $('cardAlunoLogin');
      if (card) card.scrollIntoView({ behavior: 'smooth', block: 'start' });
      var inp = $('alunoLoginNome');
      if (inp) inp.focus();
    } catch (e2) {}
  }, 200);
};

Simulador.trocarAvatar = function () {
  var aluno = alunoLogado();
  if (!aluno) return;
  $('simAreaJogo').style.display = "none";
  $('simAreaLogin').style.display = "block";
  Simulador.renderEscolhaAvatar(aluno);
};

/* Avatares customizados salvos no aparelho (localStorage) e no cadastro do aluno */
Simulador.CUSTOM_KEY = 'uc_avatares_custom_v1';
Simulador.carregarCustomLocal = function () {
  try { return JSON.parse(localStorage.getItem(Simulador.CUSTOM_KEY) || '[]'); } catch (e) { return []; }
};
Simulador.salvarCustomLocal = function (lista) {
  try { localStorage.setItem(Simulador.CUSTOM_KEY, JSON.stringify(lista)); } catch (e) {}
};
Simulador.obterPersonagem = function (chave) {
  if (Simulador.personagens[chave]) return Simulador.personagens[chave];
  var custom = Simulador.carregarCustomLocal().find(function (c) { return c.id === chave; });
  if (custom) {
    return {
      nome: custom.nome || 'Avatar Custom',
      atributos: custom.atributos || { forca: 70, velocidade: 70, agilidade: 70 },
      movimentos: custom.movimentos || ['Ginga', 'Rasteira', 'Meia-Lua'],
      especial: custom.especial || 'Golpe Especial',
      custom: true,
      img: custom.img
    };
  }
  var aluno = alunoLogado();
  if (aluno && aluno.avatarCustomId === chave && aluno.avatarCustomImg) {
    return {
      nome: aluno.apelidoAvatarSimulador || 'Meu Avatar',
      atributos: (aluno.avatarAprendizado && aluno.avatarAprendizado.atributos) || { forca: 70, velocidade: 70, agilidade: 70 },
      movimentos: ['Ginga', 'Rasteira', 'Meia-Lua'],
      especial: 'Golpe Aprendido',
      custom: true,
      img: aluno.avatarCustomImg
    };
  }
  return null;
};
Simulador.obterImagem = function (chave) {
  if (Simulador.imagens[chave]) return Simulador.imagens[chave];
  var p = Simulador.obterPersonagem(chave);
  return (p && p.img) || null;
};

/* Sistema de aprendizado: o avatar evolui com as ações do aluno */
Simulador.obterAprendizado = function (aluno) {
  var a = (aluno && aluno.avatarAprendizado) || {};
  return {
    totalTreinos: a.totalTreinos || 0,
    totalCombates: a.totalCombates || 0,
    totalCuidados: a.totalCuidados || 0,
    golpes: a.golpes || {},
    estilo: a.estilo || 'iniciante',
    bonusPrecisao: a.bonusPrecisao || 0,
    bonusImpacto: a.bonusImpacto || 0,
    atributos: a.atributos || null
  };
};
Simulador.registrarAprendizado = function (tipo, detalhe) {
  var aluno = alunoLogado();
  if (!aluno || !sessaoAlunoId) return Promise.resolve();
  var apr = Simulador.obterAprendizado(aluno);
  if (tipo === 'treino') {
    apr.totalTreinos += 1;
    apr.bonusImpacto = Math.min(25, (apr.bonusImpacto || 0) + 1);
  } else if (tipo === 'combate') {
    apr.totalCombates += 1;
    var golpe = detalhe || 'golpe';
    apr.golpes[golpe] = (apr.golpes[golpe] || 0) + 1;
    apr.bonusPrecisao = Math.min(30, (apr.bonusPrecisao || 0) + 1);
  } else if (tipo === 'cuidado') {
    apr.totalCuidados += 1;
  }
  var total = apr.totalTreinos + apr.totalCombates + Math.floor(apr.totalCuidados / 3);
  if (total >= 40) apr.estilo = 'mestre';
  else if (total >= 20) apr.estilo = 'avancado';
  else if (total >= 8) apr.estilo = 'intermediario';
  else apr.estilo = 'iniciante';
  return DB.atualizar('alunos', sessaoAlunoId, { avatarAprendizado: apr }).then(function () {
    Simulador.atualizarUIAprendizado();
    return apr;
  });
};
Simulador.atualizarUIAprendizado = function () {
  var aluno = alunoLogado();
  if (!aluno) return;
  var apr = Simulador.obterAprendizado(aluno);
  var box = $('simBarrasAprendizado');
  var txt = $('simTxtAprendizado');
  if (txt) {
    txt.textContent = 'Estilo: ' + apr.estilo.toUpperCase() +
      ' · Treinos: ' + apr.totalTreinos +
      ' · Combates: ' + apr.totalCombates +
      ' · Cuidados: ' + apr.totalCuidados +
      ' · Bônus precisão +' + apr.bonusPrecisao + '% · impacto +' + apr.bonusImpacto + '%';
  }
  if (box) {
    var topGolpes = Object.keys(apr.golpes).sort(function (a, b) { return apr.golpes[b] - apr.golpes[a]; }).slice(0, 3);
    box.innerHTML = topGolpes.length
      ? 'Golpes favoritos: ' + topGolpes.map(function (g) { return g + ' (' + apr.golpes[g] + ')'; }).join(' · ')
      : 'Ainda sem golpes registrados — treine e lute para o avatar aprender.';
  }
};

Simulador.renderEscolhaAvatar = function (aluno) {
  var modoProfessor = (function () {
    var b = $('btnToggleEquipe');
    return !!(b && b.style.display !== 'none');
  })();

  var apelidoPadrao = aluno.apelidoAvatarSimulador || aluno.apelido || aluno.nome || '';

  var html = '<div class="card"><h3><i class="fas fa-user-astronaut"></i> Escolha seu avatar</h3>' +
    '<label class="campo-label">Apelido do avatar</label>' +
    '<input id="simInputApelido" value="' + esc(apelidoPadrao) + '" placeholder="Apelido do avatar">' +
    '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:10px 0;" id="simGridAvatares"></div>' +
    '<label class="campo-label">Ou adicione do armazenamento do aparelho</label>' +
    '<input type="file" id="simInputCustomAvatar" accept="image/*" style="margin-bottom:8px;">' +
    '<p class="mini" style="margin-bottom:8px;">A imagem fica salva no seu cadastro e no aparelho (base64). O avatar aprende com seus treinos.</p>' +
    '<button class="btn" onclick="Simulador.confirmarAvatar()"><i class="fas fa-check"></i> Confirmar</button></div>';

  $('simAreaLogin').innerHTML = html;
  var grid = $('simGridAvatares');

  function marcarCard(card, chave) {
    grid.querySelectorAll('[data-chave]').forEach(function (c) { c.style.borderColor = 'var(--card-border)'; });
    card.style.borderColor = 'var(--primary-green)';
    Simulador.avatarSelecionadoTemp = chave;
  }

  Object.keys(Simulador.personagens).forEach(function (chave) {
    var p = Simulador.personagens[chave];
    var ehProfessor = p.exclusivo === 'professor';
    if (ehProfessor && !modoProfessor) return;
    if (!ehProfessor && modoProfessor) return;
    var img = Simulador.imagens[chave];
    var card = document.createElement('div');
    card.style.cssText = 'background:var(--card-bg);border:2px solid var(--card-border);border-radius:8px;padding:4px;text-align:center;cursor:pointer;';
    card.dataset.chave = chave;
    card.innerHTML = (img ? '<img src="' + img + '" style="width:100%;aspect-ratio:1;object-fit:contain;border-radius:6px;background:#000;">'
        : '<div style="width:100%;aspect-ratio:1;background:#000;border-radius:6px;"></div>') +
      '<div class="mini" style="margin-top:2px;">' + esc(p.nome) + '</div>';
    card.onclick = function () { marcarCard(card, chave); };
    grid.appendChild(card);
  });

  /* Avatares custom salvos no aparelho */
  Simulador.carregarCustomLocal().forEach(function (c) {
    var card = document.createElement('div');
    card.style.cssText = 'background:var(--card-bg);border:2px solid var(--card-border);border-radius:8px;padding:4px;text-align:center;cursor:pointer;';
    card.dataset.chave = c.id;
    card.innerHTML = '<img src="' + c.img + '" style="width:100%;aspect-ratio:1;object-fit:contain;border-radius:6px;background:#000;">' +
      '<div class="mini" style="margin-top:2px;">' + esc(c.nome || 'Custom') + '</div>';
    card.onclick = function () { marcarCard(card, c.id); };
    grid.appendChild(card);
  });

  var fileInput = $('simInputCustomAvatar');
  if (fileInput) {
    fileInput.onchange = function () {
      var file = fileInput.files && fileInput.files[0];
      if (!file) return;
      if (file.size > 900000) {
        try { mostrarToast('Imagem muito grande (máx ~900KB).', 'erro'); } catch (e) { alert('Imagem muito grande.'); }
        return;
      }
      var reader = new FileReader();
      reader.onload = function () {
        var dataUrl = reader.result;
        var id = 'custom_' + Date.now();
        var nome = ($('simInputApelido').value || '').trim() || (file.name.replace(/\.[^.]+$/, '') || 'Meu Avatar');
        var lista = Simulador.carregarCustomLocal();
        lista.push({
          id: id,
          nome: nome,
          img: dataUrl,
          atributos: { forca: 70, velocidade: 70, agilidade: 70 },
          movimentos: ['Ginga', 'Rasteira', 'Meia-Lua'],
          especial: 'Golpe Aprendido',
          criadoEm: agoraISO()
        });
        Simulador.salvarCustomLocal(lista);
        Simulador.avatarSelecionadoTemp = id;
        Simulador._pendingCustomImg = dataUrl;
        Simulador._pendingCustomNome = nome;
        /* preview no grid */
        var card = document.createElement('div');
        card.style.cssText = 'background:var(--card-bg);border:2px solid var(--primary-green);border-radius:8px;padding:4px;text-align:center;cursor:pointer;';
        card.dataset.chave = id;
        card.innerHTML = '<img src="' + dataUrl + '" style="width:100%;aspect-ratio:1;object-fit:contain;border-radius:6px;background:#000;">' +
          '<div class="mini" style="margin-top:2px;">' + esc(nome) + '</div>';
        card.onclick = function () { marcarCard(card, id); };
        grid.appendChild(card);
        try { mostrarToast('Avatar do aparelho adicionado! Confirme para usar.'); } catch (e2) {}
      };
      reader.readAsDataURL(file);
    };
  }
};

Simulador.confirmarAvatar = function () {
  if (!Simulador.avatarSelecionadoTemp) { try { mostrarToast('Escolha um avatar.', 'erro'); } catch (e) { alert('Escolha um avatar.'); } return; }
  var chave = Simulador.avatarSelecionadoTemp;
  var p = Simulador.obterPersonagem(chave);
  var apelido = ($('simInputApelido').value || '').trim() || (p && p.nome) || 'Avatar';
  var payload = {
    avatarSimulador: chave,
    apelidoAvatarSimulador: apelido
  };
  if (chave.indexOf('custom_') === 0) {
    var img = Simulador._pendingCustomImg || (p && p.img) || null;
    payload.avatarCustomId = chave;
    if (img) payload.avatarCustomImg = img;
  }
  DB.atualizar('alunos', sessaoAlunoId, payload).then(function () {
    try { publicarPresencaAvatar(); } catch (e) {}
    Simulador.render();
  });
};

/* ------------------------------------------------------------
   Tela de jogo: canvas com o avatar animado (ginga),
   treino e combate. Avatar aprende com o aluno (JS).
   Terreiro + Tamagotchi unificados no Simulador.
   ------------------------------------------------------------ */
Simulador._frameBalanco = 0;
Simulador._canvas = null;
Simulador._ctx = null;
Simulador._imgObjCache = {};

Simulador.iniciarJogo = function (aluno) {
  var chave = aluno.avatarSimulador;
  var p = Simulador.obterPersonagem(chave);
  if (!p) {
    Simulador.renderEscolhaAvatar(aluno);
    return;
  }

  /* garante estado de energia também para avatares custom */
  if (!Simulador.estadoBatalha[chave]) Simulador.estadoBatalha[chave] = { energia: 100 };

  $('simTxtJogador').innerText = aluno.apelidoAvatarSimulador || aluno.apelido || aluno.nome;
  var nivel = aluno.nivelSimulador || 1;
  $('simTxtGraduacao').innerText = 'Corda: ' + (aluno.graduacao || 'Corda Crua') + ' (Nivel ' + nivel + ')';
  if ($('simBarEnergia')) $('simBarEnergia').style.width = Simulador.estadoBatalha[chave].energia + '%';
  Simulador.atualizarBarrasCuidado(aluno);
  Simulador.atualizarUIAprendizado();

  var box = $('simBoxCombate');
  if (box) {
    box.innerHTML = '';
    p.movimentos.forEach(function (mov, idx) {
      var btn = document.createElement('button');
      btn.className = 'btn';
      btn.style.background = ['#d35400', '#9b59b6', '#2980b9'][idx] || '#555';
      btn.innerText = mov;
      btn.onclick = (function (indiceFixo) { return function () { Simulador.jogarTurno(chave, indiceFixo); }; })(idx);
      box.appendChild(btn);
    });
    if (p.especial) {
      var btnEsp = document.createElement('button');
      btnEsp.className = 'btn btn-gold';
      btnEsp.innerText = '⭐ ' + p.especial;
      btnEsp.onclick = function () { Simulador.jogarTurno(chave, -1); };
      box.appendChild(btnEsp);
    }
  }

  var srcImg = Simulador.obterImagem(chave);
  if (srcImg && !Simulador._imgObjCache[chave]) {
    var im = new Image();
    im.src = srcImg;
    Simulador._imgObjCache[chave] = im;
  }

  Simulador._canvas = $('simCanvas');
  Simulador._ctx = Simulador._canvas.getContext('2d');
  Simulador._canvas.width = Simulador._canvas.clientWidth || 320;
  Simulador._canvas.height = 220;

  try { publicarPresencaAvatar(); renderTerreiroListas(); Simulador.renderTerreiroLocal(); } catch (e) {}

  if (Simulador._loopAtivo) return;
  Simulador._loopAtivo = true;
  Simulador._loop();
};

Simulador.renderTerreiroLocal = function () {
  var box = $('listaTerreiroSimulador');
  if (!box) return;
  try {
    var lista = (typeof listarAvataresVisiveis === 'function') ? listarAvataresVisiveis() : [];
    if (!lista.length) {
      box.innerHTML = '<p class="sem-dados" style="grid-column:1/-1;">Ninguém no terreiro agora. Faça login e escolha um avatar.</p>';
      return;
    }
    box.innerHTML = lista.map(function (a) {
      return (typeof htmlAvatarChip === 'function') ? htmlAvatarChip(a, true) :
        '<div class="mini">' + esc(a.alunoApelido || a.alunoNome || '?') + '</div>';
    }).join('');
  } catch (e) {
    box.innerHTML = '<p class="sem-dados">Terreiro indisponível no momento.</p>';
  }
};

/* Mapa personagem Simulador → id do motor pixel (Tamagotchi) */
Simulador.PIXEL_MAP = {
  rootsGinga: 'roots', urbanSkater: 'urban', neonStriker: 'neon',
  tribalBalance: 'tribal', tribal2: 'elder', stealthMartial: 'stealth',
  futuroBananeira: 'futuro', classicChute: 'classic', reggaeRhythm: 'reggae',
  mysticFlow: 'mystic', sereno: 'roots', agulha: 'classic', onca: 'stealth',
  professor: 'elder'
};
Simulador._poseAtual = 'ginga'; /* ginga | chute | guarda | danca | bananeira */
Simulador._poseAte = 0;

Simulador.setPose = function (pose, ms) {
  Simulador._poseAtual = pose || 'ginga';
  Simulador._poseAte = Date.now() + (ms || 900);
};

Simulador._loop = function () {
  var canvas = Simulador._canvas, ctx = Simulador._ctx;
  if (canvas && ctx) {
    var w = canvas.width, h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    /* fundo estilo terreiro */
    var g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#0d3d1f');
    g.addColorStop(0.55, '#0a2a38');
    g.addColorStop(1, '#061018');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(0,230,118,0.1)';
    ctx.fillRect(0, h - 28, w, 28);
    ctx.strokeStyle = 'rgba(255,193,7,0.25)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.ellipse(w / 2, h - 18, w * 0.36, 10, 0, 0, Math.PI * 2);
    ctx.stroke();

    Simulador._frameBalanco += 0.06;
    var dx = Math.sin(Simulador._frameBalanco) * 8;
    var dy = Math.abs(Math.cos(Simulador._frameBalanco)) * 3;

    var aluno = alunoLogado();
    var chave = aluno && aluno.avatarSimulador;
    var im = chave && Simulador._imgObjCache[chave];
    var ehCustom = chave && String(chave).indexOf('custom_') === 0;

    /* pose temporária após golpe/defesa */
    if (Date.now() > Simulador._poseAte) Simulador._poseAtual = 'ginga';

    if (!ehCustom && typeof tamaDrawPixelChar === 'function' && typeof TAMA_CHARS !== 'undefined') {
      var pixelId = Simulador.PIXEL_MAP[chave] || 'roots';
      var ch = null;
      for (var i = 0; i < TAMA_CHARS.length; i++) {
        if (TAMA_CHARS[i].id === pixelId) { ch = TAMA_CHARS[i]; break; }
      }
      if (ch && typeof PIXEL_TAMA_CFG !== 'undefined') {
        /* aplica pose no cfg temporariamente */
        var cfgBase = PIXEL_TAMA_CFG[pixelId] || PIXEL_TAMA_CFG.roots;
        var movOriginal = cfgBase.movimento;
        if (Simulador._poseAtual === 'chute') cfgBase.movimento = 'chute';
        else if (Simulador._poseAtual === 'guarda') cfgBase.movimento = 'guarda';
        else if (Simulador._poseAtual === 'bananeira') cfgBase.movimento = 'bananeira';
        else if (Simulador._poseAtual === 'danca') cfgBase.movimento = 'danca';
        else cfgBase.movimento = movOriginal || 'ginga';

        tamaDrawPixelChar(ctx, ch, w / 2 + dx * 0.3, h * 0.42 + dy, 1.25, 0);
        cfgBase.movimento = movOriginal;
      } else if (im && im.complete && im.naturalWidth > 0) {
        var tam = 120;
        ctx.drawImage(im, w / 2 - tam / 2 + dx, 40 + dy, tam, tam);
      }
    } else if (im && im.complete && im.naturalWidth > 0) {
      var tam2 = 120;
      ctx.drawImage(im, w / 2 - tam2 / 2 + dx, 40 + dy, tam2, tam2);
    } else if (chave) {
      ctx.fillStyle = '#00e676';
      ctx.beginPath();
      ctx.arc(w / 2 + dx, 100 + dy, 40, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  requestAnimationFrame(Simulador._loop);
};

/* Combate com aprendizado: bônus de precisão/impacto do aluno */
Simulador.executarMovimento = function (chave, indice) {
  var p = Simulador.obterPersonagem(chave);
  var estado = Simulador.estadoBatalha[chave];
  if (!p || !estado) return "Personagem nao encontrado.";
  if (estado.energia < 15) return p.nome + " esta exausto! Precisa descansar na ginga.";
  var golpe = (indice === -1) ? p.especial : (p.movimentos[indice] || p.especial);
  var custo = (golpe === p.especial) ? 30 : 15;
  estado.energia = Math.max(0, estado.energia - custo);

  var aluno = alunoLogado();
  var apr = Simulador.obterAprendizado(aluno);
  var basePrec = Math.floor(Math.random() * (p.atributos.agilidade || 70));
  var baseImp = Math.floor(((p.atributos.forca || 70) * (p.atributos.velocidade || 70)) / 100);
  var precisao = Math.min(100, basePrec + (apr.bonusPrecisao || 0));
  var impacto = Math.min(150, baseImp + (apr.bonusImpacto || 0));

  return {
    texto: p.nome + " aplicou [" + golpe + "]!" + (apr.estilo !== 'iniciante' ? ' (estilo ' + apr.estilo + ')' : ''),
    precisao: precisao,
    impacto: impacto,
    energiaRestante: estado.energia,
    golpe: golpe
  };
};

Simulador.jogarTurno = function (chave, indice) {
  var r = Simulador.executarMovimento(chave, indice);
  var cons = $('simConsole');
  if (typeof r === 'string') {
    if (cons) cons.innerHTML = r;
  } else {
    /* anima pose no canvas conforme o golpe */
    if (indice === -1) Simulador.setPose('bananeira', 1200);
    else if (indice === 2) Simulador.setPose('guarda', 900);
    else if (indice === 1) Simulador.setPose('danca', 900);
    else Simulador.setPose('chute', 900);

    if (cons) cons.innerHTML = r.texto + ' Impacto: ' + r.impacto + ' | Precisão: ' + r.precisao;
    if ($('simBarEnergia')) $('simBarEnergia').style.width = r.energiaRestante + '%';
    Simulador.registrarAprendizado('combate', r.golpe).then(function (apr) {
      if (cons && apr) {
        cons.innerHTML += '<br><span style="color:var(--gold);">Avatar aprendeu! Estilo: ' + apr.estilo +
          ' · Bônus precisão +' + apr.bonusPrecisao + '%</span>';
      }
    });
  }
};

Simulador.treinar = function () {
  var aluno = alunoLogado();
  if (!aluno) return;
  var chave = aluno.avatarSimulador;
  if (!Simulador.estadoBatalha[chave]) Simulador.estadoBatalha[chave] = { energia: 100 };
  var treinos = (aluno.treinosSimulador || 0) + 1;
  var nivel = (aluno.nivelSimulador || 1) + 1;
  /* graduação/corda NÃO é alterada aqui — só nível de treino do avatar */
  DB.atualizar('alunos', sessaoAlunoId, {
    treinosSimulador: treinos,
    nivelSimulador: nivel
  }).then(function () {
    Simulador.descansar(chave);
    if ($('simTxtGraduacao')) $('simTxtGraduacao').innerText = 'Corda: ' + (aluno.graduacao || 'Corda Crua') + ' (Nivel ' + nivel + ')';
    if ($('simBarEnergia')) $('simBarEnergia').style.width = Simulador.estadoBatalha[chave].energia + '%';
    Simulador.registrarAprendizado('treino').then(function (apr) {
      var cons = $('simConsole');
      if (cons) cons.innerHTML = 'Treino confirmado! Avatar evoluiu (estilo ' + (apr && apr.estilo || 'iniciante') + ').';
    });
  });
};

/* Cuidar do avatar (Tamagotchi) — estado no cadastro do aluno */
Simulador.atualizarBarrasCuidado = function (aluno) {
  var fome = (aluno.fomeSimulador != null) ? aluno.fomeSimulador : 100;
  var humor = (aluno.humorSimulador != null) ? aluno.humorSimulador : 100;
  if ($('simBarFome')) $('simBarFome').style.width = fome + '%';
  if ($('simBarHumor')) $('simBarHumor').style.width = humor + '%';
};

Simulador.alimentar = function () {
  var aluno = alunoLogado();
  if (!aluno) return;
  var fome = Math.min(100, (aluno.fomeSimulador != null ? aluno.fomeSimulador : 100) + 20);
  DB.atualizar('alunos', sessaoAlunoId, { fomeSimulador: fome }).then(function () {
    if ($('simBarFome')) $('simBarFome').style.width = fome + '%';
    var cons = $('simConsole');
    if (cons) cons.innerHTML = 'Avatar alimentado! Fome: ' + Math.round(fome) + '%';
    Simulador.registrarAprendizado('cuidado');
  });
};

Simulador.alongar = function () {
  var aluno = alunoLogado();
  if (!aluno) return;
  var humor = Math.min(100, (aluno.humorSimulador != null ? aluno.humorSimulador : 100) + 15);
  var chave = aluno.avatarSimulador;
  if (!Simulador.estadoBatalha[chave]) Simulador.estadoBatalha[chave] = { energia: 100 };
  DB.atualizar('alunos', sessaoAlunoId, { humorSimulador: humor }).then(function () {
    if ($('simBarHumor')) $('simBarHumor').style.width = humor + '%';
    Simulador.descansar(chave);
    if ($('simBarEnergia')) $('simBarEnergia').style.width = Simulador.estadoBatalha[chave].energia + '%';
    var cons = $('simConsole');
    if (cons) cons.innerHTML = 'Avatar alongou! Humor: ' + Math.round(humor) + '%, energia recuperada.';
    Simulador.registrarAprendizado('cuidado');
  });
};

Simulador.controleFlutuante = function (comando) {
  var aluno = alunoLogado();
  if (!aluno) return;
  var chave = aluno.avatarSimulador;
  var cons = $('simConsole');
  if (comando === 'golpe') { Simulador.setPose('chute', 800); Simulador.jogarTurno(chave, 0); return; }
  if (comando === 'defesa') { Simulador.setPose('guarda', 800); Simulador.jogarTurno(chave, 2); return; }
  if (comando === 'esquerda' || comando === 'direita') {
    Simulador.setPose('danca', 500);
    if (cons) cons.innerHTML = 'Ginga para a ' + (comando === 'esquerda' ? 'esquerda' : 'direita') + '!';
    return;
  }
  if (cons) cons.innerHTML = 'Movimento [' + comando + '] executado.';
};

/* persiste a sessão do aluno para conveniência */

/* ============================================================
   MUNDO = TAMAGOTCHI CAPOEIRA (substitui a antiga tela do Simulador)
   Tudo no objeto Tama. Salva no cadastro do aluno logado (aluno.tamagotchi)
   e no aparelho (localStorage) como reserva.
   ============================================================ */
var Tama = {
  KEY: 'uc_tama_v1',
  lutaAtiva: null,
  AV: [
    { id: 'ginga', nome: 'Ginginha', e: '🥋', a: 'a1' }, { id: 'berimbau', nome: 'Berimbauzinho', e: '🎼', a: 'a2' },
    { id: 'angola', nome: 'Angolinha', e: '🤸', a: 'a4' }, { id: 'regional', nome: 'Regionalzinho', e: '🥊', a: 'a3' },
    { id: 'mestre', nome: 'Mestrinho', e: '👑', a: 'a4' }, { id: 'leao', nome: 'Leãozinho', e: '🦁', a: 'a3' },
    { id: 'mago', nome: 'Magozinho', e: '🧙', a: 'a4' }, { id: 'ninja', nome: 'Ninjinha', e: '🥷', a: 'a2' }
  ],
  MOV: [
    { nome: 'Rasteira', custo: 10, dano: 15 }, { nome: 'Meia-Lua', custo: 14, dano: 22 },
    { nome: 'Armada', custo: 16, dano: 25 }, { nome: 'Cabeçada', custo: 22, dano: 35 },
    { nome: 'Aú (esquiva)', custo: 8, dano: 0, defesa: true }
  ]
};
Tama.av = function (m) { return Tama.AV.filter(function (a) { return a.id === m.charId; })[0] || Tama.AV[0]; };

Tama.carregar = function () {
  var m = null, aluno = (typeof alunoLogado === 'function') ? alunoLogado() : null;
  if (aluno && aluno.tamagotchi) m = aluno.tamagotchi;
  else { try { m = JSON.parse(localStorage.getItem(Tama.KEY) || 'null'); } catch (e) {} }
  if (!m) return null;
  m = JSON.parse(JSON.stringify(m));
  /* com o tempo, os status caem (a cada 3 min); só em memória até uma ação salvar */
  var blocos = Math.floor((Date.now() - new Date(m.ultimoCuidado).getTime()) / 180000);
  if (blocos > 0 && m.status !== 'morto') {
    m.fome = Math.max(0, m.fome - blocos * 3); m.energia = Math.max(0, m.energia - blocos * 2);
    m.humor = Math.max(0, m.humor - blocos * 2); m.forma = Math.max(0, m.forma - blocos);
    m.ultimoCuidado = new Date().toISOString();
    if (m.fome <= 0 || m.energia <= 0) m.status = 'doente';
    if (m.fome <= 0 && m.energia <= 0 && m.humor <= 0) m.status = 'morto';
  }
  return m;
};
Tama.salvar = function (m) {
  try { localStorage.setItem(Tama.KEY, JSON.stringify(m)); } catch (e) {}
  var aluno = (typeof alunoLogado === 'function') ? alunoLogado() : null;
  if (aluno) { try { DB.atualizar('alunos', aluno.id, { tamagotchi: m }); } catch (e2) {} }
};

Tama.emoji = function (m) {
  var av = Tama.av(m);
  if (m.status === 'morto') return '👻';
  if (m.status === 'doente') return '🤒';
  if (m.fome < 25) return '😿'; if (m.energia < 25) return '😴';
  if (m.humor < 25) return '😾'; if (m.forma < 25) return '😰';
  return av.e;
};
Tama.texto = function (m) {
  if (m.status === 'morto') return 'Inativo. Troque de mascote.';
  if (m.status === 'doente') return 'Estou doente… preciso de remédio!';
  if (m.fome < 25) return 'Fome intensa!'; if (m.energia < 25) return 'Sono profundo.';
  if (m.humor < 25) return 'Entediado.'; if (m.forma < 25) return 'Preciso treinar!';
  return (m.fome + m.energia + m.humor + m.forma) / 4 >= 85 ? 'Axé total! 💚' : 'Pronto para a ginga.';
};

Tama.render = function () {
  var root = $('tamaRoot'); if (!root) return;
  var m = Tama.carregar();
  if (!m || !m.charId) { root.innerHTML = Tama.htmlEscolha(); return; }
  var av = Tama.av(m), L = Tama.lutaAtiva, arena = '';
  if (L) {
    arena = '<div class="tm-arena"><div class="tm-hud"><span style="color:#00e676">Você: HP ' + L.hpP + '%</span>' +
      '<span style="color:#ff5252">Rival: HP ' + L.hpR + '%</span></div>' +
      '<div class="mini" style="margin-bottom:6px">Energia: ' + L.enP + '</div><div class="tm-moves">' +
      Tama.MOV.map(function (mv, i) {
        return '<button class="btn btn-mini" ' + (L.enP < mv.custo ? 'disabled ' : '') + 'onclick="Tama.turno(' + i + ')">' + mv.nome + '</button>';
      }).join('') + '</div><button class="btn btn-mini" style="margin-top:8px" onclick="Tama.fugir()">Desistir</button></div>';
  }
  root.innerHTML =
    '<div class="card"><div class="tm-stats">' +
    ['Fome', 'Energia', 'Humor', 'Forma'].map(function (n) { return '<div class="tm-stat">' + n + '<div class="tm-bar"><i id="tmb' + n + '"></i></div></div>'; }).join('') +
    '</div><div class="tm-stage"><div id="tmPet" class="tm-pet ' + av.a + (m.status === 'morto' ? ' morto' : '') + '">' + Tama.emoji(m) + '</div>' +
    '<div id="tmAct" class="tm-act">' + esc(Tama.texto(m)) + '</div></div>' +
    '<div class="linha mini" style="margin-top:10px;display:flex;justify-content:space-between"><span><b>' + esc(m.nome) + '</b> · Nv.' + m.nivel + '</span><span id="tmXp">XP ' + m.xp + '/' + (m.nivel * 100) + ' · 🏆 ' + m.vitorias + '</span></div>' +
    '<div class="tm-ctl">' +
    '<button class="tm-btn" onclick="Tama.acao(\'feed\')"><i class="fas fa-apple-alt"></i>Alimentar</button>' +
    '<button class="tm-btn" onclick="Tama.acao(\'train\')"><i class="fas fa-dumbbell"></i>Treinar</button>' +
    '<button class="tm-btn" onclick="Tama.acao(\'sleep\')"><i class="fas fa-moon"></i>Dormir</button>' +
    '<button class="tm-btn" onclick="Tama.acao(\'play\')"><i class="fas fa-gamepad"></i>Brincar</button>' +
    '<button class="tm-btn" onclick="Tama.iniciarLuta()"><i class="fas fa-fist-raised"></i>Lutar</button>' +
    '<button class="tm-btn" onclick="Tama.acao(\'med\')"><i class="fas fa-pills"></i>Remédio</button>' +
    '<button class="tm-btn tm-wide" onclick="Tama.trocar()"><i class="fas fa-user-edit"></i>Trocar mascote</button></div>' +
    arena + '<div class="tm-log" id="tmLog">Bem-vindo ao Mundo! ▸</div></div>';
  Tama.barras(m);
};

Tama.barras = function (m) {
  [['Fome', m.fome], ['Energia', m.energia], ['Humor', m.humor], ['Forma', m.forma]].forEach(function (p) {
    var el = $('tmb' + p[0]); if (!el) return;
    el.style.width = Math.max(0, Math.min(100, p[1])) + '%';
    el.style.background = p[1] > 50 ? '#10b981' : (p[1] > 20 ? '#f59e0b' : '#ef4444');
  });
};
Tama.refresh = function () {
  var m = Tama.carregar(), tab = $('tabSimulador');
  if (!m || !tab || !tab.classList.contains('active') || Tama.lutaAtiva) return;
  Tama.barras(m);
  if ($('tmPet')) $('tmPet').textContent = Tama.emoji(m);
  if ($('tmAct')) $('tmAct').textContent = Tama.texto(m);
};
Tama.log = function (t) { var el = $('tmLog'); if (el) el.innerHTML = '<div>▸ ' + esc(t) + '</div>' + el.innerHTML; };

Tama.htmlEscolha = function () {
  return '<div class="card"><h3><i class="fas fa-dog"></i> Escolha seu Mascote</h3>' +
    '<div class="tm-pick">' + Tama.AV.map(function (a) {
      return '<div class="tm-card" data-id="' + a.id + '" onclick="Tama.pick(this)"><b>' + a.e + '</b><span>' + a.nome + '</span></div>';
    }).join('') + '</div><label class="campo-label" style="margin-top:12px;display:block">Apelido</label>' +
    '<input id="tmApelido" maxlength="20" placeholder="Ex: Ginginha"><button class="btn btn-gold" style="margin-top:10px" onclick="Tama.adotar()">Adotar</button></div>';
};
Tama.pick = function (el) {
  Array.prototype.forEach.call(document.querySelectorAll('.tm-card'), function (c) { c.classList.remove('sel'); });
  el.classList.add('sel');
};
Tama.adotar = function () {
  var sel = document.querySelector('.tm-card.sel');
  if (!sel) return mostrarToast('Selecione um mascote.', 'erro');
  var av = Tama.AV.filter(function (a) { return a.id === sel.getAttribute('data-id'); })[0];
  var ap = (($('tmApelido') || {}).value || '').trim();
  var alu = (typeof alunoLogado === 'function') ? alunoLogado() : null;
  Tama.salvar({ charId: av.id, nome: ap || (alu && alu.apelido) || av.nome, fome: 85, energia: 85, humor: 85, forma: 70,
    nivel: 1, xp: 0, treinos: 0, vitorias: 0, status: 'vivo', ultimoCuidado: new Date().toISOString() });
  mostrarToast('Mascote adotado! 💚'); Tama.render();
};
Tama.trocar = function () {
  var m = Tama.carregar(); if (!m) return;
  m.charId = null; Tama.lutaAtiva = null; Tama.salvar(m); Tama.render();
};

Tama.nivel = function (m) {
  while (m.xp >= m.nivel * 100 && m.nivel < 50) { m.xp -= m.nivel * 100; m.nivel++; mostrarToast('⬆️ Nível ' + m.nivel + '!'); }
};
Tama.acao = function (t) {
  var m = Tama.carregar(); if (!m) return;
  if (m.status === 'morto' && t !== 'med') return mostrarToast('Mascote inativo. Troque de mascote.', 'erro');
  if (t === 'feed') m.fome = Math.min(100, m.fome + 28);
  if (t === 'train') { m.forma = Math.min(100, m.forma + 20); m.energia = Math.max(0, m.energia - 12); m.treinos++; m.xp += 8; }
  if (t === 'sleep') m.energia = Math.min(100, m.energia + 40);
  if (t === 'play') m.humor = Math.min(100, m.humor + 25);
  if (t === 'med') { m.status = 'vivo'; m.fome = Math.max(m.fome, 30); m.energia = Math.max(m.energia, 30); }
  if (m.status === 'doente' && m.fome > 40 && m.energia > 40) m.status = 'vivo';
  Tama.nivel(m); m.ultimoCuidado = new Date().toISOString();
  Tama.salvar(m); Tama.barras(m);
  if ($('tmPet')) $('tmPet').textContent = Tama.emoji(m);
  if ($('tmAct')) $('tmAct').textContent = Tama.texto(m);
  if ($('tmXp')) $('tmXp').textContent = 'XP ' + m.xp + '/' + (m.nivel * 100) + ' · 🏆 ' + m.vitorias;
  Tama.log({ feed: 'Comeu bem!', train: 'Treinou a ginga (+XP).', sleep: 'Descansou.', play: 'Brincou na roda!', med: 'Tomou o remédio.' }[t]);
};

/* ---- Luta: o rival usa Minimax (profundidade 3) ---- */
Tama.minimax = function (hpP, hpR, enP, enR, prof, vezRival) {
  if (prof === 0 || hpP <= 0 || hpR <= 0) return { s: (hpR - hpP) * 2 + (enR - enP) * 0.5 };
  var melhor = { s: vezRival ? -Infinity : Infinity }, algum = false;
  Tama.MOV.forEach(function (mv) {
    var en = vezRival ? enR : enP; if (en < mv.custo) return;
    algum = true;
    var r = vezRival
      ? Tama.minimax(mv.defesa ? hpP : hpP - mv.dano, hpR, enP, enR - mv.custo + 10, prof - 1, false)
      : Tama.minimax(hpP, mv.defesa ? hpR : hpR - mv.dano, enP - mv.custo + 10, enR, prof - 1, true);
    if (vezRival ? r.s > melhor.s : r.s < melhor.s) melhor = { s: r.s, mv: mv };
  });
  return algum ? melhor : { s: (hpR - hpP) * 2 + (enR - enP) * 0.5 };
};
Tama.iniciarLuta = function () {
  var m = Tama.carregar();
  if (!m || m.status === 'morto') return mostrarToast('Mascote inativo.', 'erro');
  if (m.energia < 20) return mostrarToast('Precisa de pelo menos 20 de energia.', 'erro');
  Tama.lutaAtiva = { hpP: 100, hpR: 100, enP: m.energia, enR: 100, guarda: false };
  Tama.render(); Tama.log('⚡ Roda iniciada contra o Mestre Rival 🦊!');
};
Tama.fugir = function () { Tama.lutaAtiva = null; Tama.render(); };
Tama.turno = function (i) {
  var L = Tama.lutaAtiva, mv = Tama.MOV[i]; if (!L || L.enP < mv.custo) return;
  var m = Tama.carregar(); L.enP -= mv.custo;
  if (mv.defesa) { L.guarda = true; L.enP = Math.min(100, L.enP + 10); Tama.log('Você se esquivou! Próximo golpe enfraquecido.'); }
  else { L.hpR = Math.max(0, L.hpR - mv.dano); Tama.log('Você usou ' + mv.nome + '! Dano ' + mv.dano + '.'); }
  if (L.hpR <= 0) {
    m.vitorias++; m.xp += 50; m.energia = Math.max(0, L.enP); m.humor = Math.min(100, m.humor + 10);
    Tama.nivel(m); m.ultimoCuidado = new Date().toISOString(); Tama.salvar(m);
    Tama.lutaAtiva = null; Tama.render(); Tama.log('🏆 Vitória! +50 XP'); return;
  }
  var d = Tama.minimax(L.hpP, L.hpR, L.enP, L.enR, 3, true), g = d.mv || Tama.MOV[0];
  if (L.enR < g.custo) g = { nome: 'Ginga', custo: 0, dano: 0 };
  var dano = g.defesa ? 0 : Math.round(g.dano * (L.guarda ? 0.5 : 1));
  L.guarda = false; L.hpP = Math.max(0, L.hpP - dano); L.enR = Math.min(100, Math.max(0, L.enR - g.custo) + 10);
  if (L.hpP <= 0) {
    m.humor = Math.max(0, m.humor - 15); m.xp += 15; m.energia = Math.max(0, L.enP);
    m.ultimoCuidado = new Date().toISOString(); Tama.nivel(m); Tama.salvar(m);
    Tama.lutaAtiva = null; Tama.render(); Tama.log('❌ Derrotado pelo Minimax. +15 XP'); return;
  }
  Tama.render(); Tama.log('🤖 Rival usou ' + g.nome + (dano ? '! Dano ' + dano + '.' : '.'));
};

/* A aba Mundo passa a mostrar o Tamagotchi */
Simulador.render = function () { Tama.render(); };
setInterval(Tama.refresh, 30000);

iniciarApp();
